=\"272\"></line><line marker-end=\"url(#marker1)\" marker-start=\"url(#marker1)\" stroke=\"#000\" stroke-dasharray=\"9 6\" stroke-width=\"2.4\" x1=\"208.89374126087537\" x2=\"239.041242426092\" y1=\"227.55555555555554\" y2=\"240.88888888888889\"></line><line marker-end=\"url(#marker2)\" marker-start=\"url(#marker2)\" stroke=\"#000\" stroke-dasharray=\"1.1 6\" stroke-linecap=\"round\" stroke-width=\"3\" x1=\"208.89374126087537\" x2=\"239.041242426092\" y1=\"94.22222222222223\" y2=\"96.44444444444446\"></line><line marker-end=\"url(#marker3)\" marker-start=\"url(#marker3)\" stroke=\"#999\" stroke-width=\"3.5\" x1=\"208.89374126087537\" x2=\"239.041242426092\" y1=\"269.77777777777777\" y2=\"256.44444444444446\"></line><line marker-end=\"url(#marker0)\" marker-start=\"url(#marker0)\" stroke=\"#000\" stroke-width=\"2.4\" x1=\"239.041242426092\" x2=\"269.1887435913086\" y1=\"272\" y2=\"272\"></line><line marker-end=\"url(#marker1)\" marker-start=\"url(#marker1)\" stroke=\"#000\" stroke-dasharray=\"9 6\" stroke-width=\"2.4\" x1=\"239.041242426092\" x2=\"269.1887435913086\" y1=\"240.88888888888889\" y2=\"265.3333333333333\"></line><line marker-end=\"url(#marker2)\" marker-start=\"url(#marker2)\" stroke=\"#000\" stroke-dasharray=\"1.1 6\" stroke-linecap=\"round\" stroke-width=\"3\" x1=\"239.041242426092\" x2=\"269.1887435913086\" y1=\"96.44444444444446\" y2=\"116.44444444444443\"></line><line marker-end=\"url(#marker3)\" marker-start=\"url(#marker3)\" stroke=\"#999\" stroke-width=\"3.5\" x1=\"239.041242426092\" x2=\"269.1887435913086\" y1=\"256.44444444444446\" y2=\"212\"></line><line marker-end=\"url(#marker0)\" marker-start=\"url(#marker0)\" stroke=\"#000\" stroke-width=\"2.4\" x1=\"269.1887435913086\" x2=\"299.3362447565252\" y1=\"272\" y2=\"272\"></line><line marker-end=\"url(#marker1)\" marker-start=\"url(#marker1)\" stroke=\"#000\" stroke-dasharray=\"9 6\" stroke-width=\"2.4\" x1=\"269.1887435913086\" x2=\"299.3362447565252\" y1=\"265.3333333333333\" y2=\"269.77777777777777\"></line><line marker-end=\"url(#marker2)\" marker-start=\"url(#marker2)\" stroke=\"#000\" stroke-dasharray=\"1.1 6\" stroke-linecap=\"round\" stroke-width=\"3\" x1=\"269.1887435913086\" x2=\"299.3362447565252\" y1=\"116.44444444444443\" y2=\"138.66666666666669\"></line><line marker-end=\"url(#marker3)\" marker-start=\"url(#marker3)\" stroke=\"#999\" stroke-width=\"3.5\" x1=\"269.1887435913086\" x2=\"299.3362447565252\" y1=\"212\" y2=\"185.33333333333331\"></line><line marker-end=\"url(#marker0)\" marker-start=\"url(#marker0)\" stroke=\"#000\" stroke-width=\"2.4\" x1=\"299.3362447565252\" x2=\"329.48374592174184\" y1=\"272\" y2=\"265.3333333333333\"></line><line marker-end=\"url(#marker1)\" marker-start=\"url(#marker1)\" stroke=\"#000\" stroke-dasharray=\"9 6\" stroke-width=\"2.4\" x1=\"299.3362447565252\" x2=\"329.48374592174184\" y1=\"269.77777777777777\" y2=\"269.77777777777777\"></line><line marker-end=\"url(#marker2)\" marker-start=\"url(#marker2)\" stroke=\"#000\" stroke-dasharray=\"1.1 6\" stroke-linecap=\"round\" stroke-width=\"3\" x1=\"299.3362447565252\" x2=\"329.48374592174184\" y1=\"138.66666666666669\" y2=\"176.44444444444446\"></line><line marker-end=\"url(#marker3)\" marker-start=\"url(#marker3)\" stroke=\"#999\" stroke-width=\"3.5\" x1=\"299.3362447565252\" x2=\"329.48374592174184\" y1=\"185.33333333333331\" y2=\"154.22222222222223\"></line><line marker-end=\"url(#marker0)\" marker-start=\"url(#marker0)\" stroke=\"#000\" stroke-width=\"2.4\" x1=\"329.48374592174184\" x2=\"359.63124708695847\" y1=\"265.3333333333333\" y2=\"238.66666666666669\"></line><line marker-end=\"url(#marker1)\" marker-start=\"url(#marker1)\" stroke=\"#000\" stroke-dasharray=\"9 6\" stroke-width=\"2.4\" x1=\"329.48374592174184\" x2=\"359.63124708695847\" y1=\"269.77777777777777\" y2=\"272\"></line><line marker-end=\"url(#marker2)\" marker-start=\"url(#marker2)\" stroke=\"#000\" stroke-dasharray=\"1.1 6\" stroke-linecap=\"round\" stroke-width=\"3\" x1=\"329.48374592174184\" x2=\"359.63124708695847\" y1=\"176.44444444444446\" y2=\"236.44444444444446\"></line><line marker-end=\"url(#marker3)\" marker-start=\"url(#marker3)\" stroke=\"#999\" stroke-width=\"3.5\" x1=\"329.48374592174184\" x2=\"359.63124708695847\" y1=\"154.22222222222223\" y2=\"118.66666666666666\"></line><line marker-end=\"url(#marker0)\" marker-start=\"url(#marker0)\" stroke=\"#000\" stroke-width=\"2.4\" x1=\"359.63124708695847\" x2=\"389.7787482521751\" y1=\"238.66666666666669\" y2=\"234.22222222222223\"></line><line marker-end=\"url(#marker1)\" marker-start=\"url(#marker1)\" stroke=\"#000\" stroke-dasharray=\"9 6\" stroke-width=\"2.4\" x1=\"359.63124708695847\" x2=\"389.7787482521751\" y1=\"272\" y2=\"272\"></line><line marker-end=\"url(#marker2)\" marker-start=\"url(#marker2)\" stroke=\"#000\" stroke-dasharray=\"1.1 6\" stroke-linecap=\"round\" stroke-width=\"3\" x1=\"359.63124708695847\" x2=\"389.7787482521751\" y1=\"236.44444444444446\" y2=\"252\"></line><line marker-end=\"url(#marker3)\" marker-start=\"url(#marker3)\" stroke=\"#999\" stroke-width=\"3.5\" x1=\"359.63124708695847\" x2=\"389.7787482521751\" y1=\"118.66666666666666\" y2=\"107.55555555555557\"></line><line marker-end=\"url(#marker0)\" marker-start=\"url(#marker0)\" stroke=\"#000\" stroke-width=\"2.4\" x1=\"389.7787482521751\" x2=\"419.9262494173917\" y1=\"234.22222222222223\" y2=\"220.88888888888889\"></line><line marker-end=\"url(#marker1)\" marker-start=\"url(#marker1)\" stroke=\"#000\" stroke-dasharray=\"9 6\" stroke-width=\"2.4\" x1=\"389.7787482521751\" x2=\"419.9262494173917\" y1=\"272\" y2=\"272\"></line><line marker-end=\"url(#marker2)\" marker-start=\"url(#marker2)\" stroke=\"#000\" stroke-dasharray=\"1.1 6\" stroke-linecap=\"round\" stroke-width=\"3\" x1=\"389.7787482521751\" x2=\"419.9262494173917\" y1=\"252\" y2=\"247.55555555555554\"></line><line marker-end=\"url(#marker3)\" marker-start=\"url(#marker3)\" stroke=\"#999\" stroke-width=\"3.5\" x1=\"389.7787482521751\" x2=\"419.9262494173917\" y1=\"107.55555555555557\" y2=\"125.33333333333334\"></line></g></svg></figure></p>\n<p>All other things being equal, the larger a wind turbine’s rotor diameter (the diameter of the imaginary circle swept by the turbine’s rotating blades), the greater amount of energy the turbine can generate. In a research paper on wind power, a student claims that in the United States, the amount of energy generated per newly installed turbine increased substantially between 2011 and 2021.</p>","stem":"<p>Which choice best describes data in the graph that support the student&rsquo;s claim?&nbsp;</p>","answerOptions":[{"id":"6f7a014d-6631-4fea-841c-33cbd4099f98","content":"<p>The percentage of newly installed turbines with rotor diameters greater than 130 meters increased every year between 2011 and 2021.&nbsp;</p>"},{"id":"464b686b-68ed-47b9-a9e9-3786099adfa9","content":"<p>In 2011, nearly 80% of turbines installed had rotor diameters of less than 100 meters, whereas only a little more than 20% of turbines installed that year had rotor diameters of 100&ndash;115 meters.&nbsp;</p>"},{"id":"57279a30-5db3-4876-9ee2-6cae3f9c8717","content":"<p>No turbines installed in 2011 had rotor diameters greater than 115 meters, whereas the majority of turbines installed in 2021 had rotor diameters greater than 130 meters.</p>"},{"id":"ced2f169-b04b-45da-a9aa-48e011e3ce04","content":"<p>Most turbines installed in 2011 had rotor diameters of less than 100 meters, whereas most turbines installed in 2021 had rotor diameters of at least 115 meters.&nbsp;</p>"}],"keys":["ced2f169-b04b-45da-a9aa-48e011e3ce04"],"correct_answer":["D"],"rationale":"<p>Choice D is the best answer. The text tells us that turbines with larger rotor diameters produce more energy, so if rotor diameters have generally gotten larger between 2011 and 2021, then turbines created in 2021 should produce more energy than those created in 2011.</p><p>Choice A is incorrect. This choice misreads the graph. The percentage of newly installed turbines with rotor diameters greater than 130 meters didn&rsquo;t show any visible increase until 2018. Choice B is incorrect. This choice doesn&rsquo;t justify the claim. The claim is about increasing energy output from 2011 to 2021, but this choice only discusses 2011, so it can&rsquo;t show evidence of change over time. Choice C is incorrect. This choice misreads the graph. In 2021, only about 25% of turbines installed in 2021 had rotor diameters greater than 130 meters.</p>","parenttemplatename":"OSP-KA-QUA-M010","parenttemplateid":"","templateclusterid":"fffe9a43-9374-4e93-b570-7d0de66fa3c0","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959371,"updateDate":1691007959371}$SATQ$::jsonb, 1691007959371, 1691007959371),
    ($SATQ$2edd7ffe$SATQ$, $SATQ$f4d5a3e3-3526-4403-9a50-294a663640d4$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Information and Ideas$SATQ$, $SATQ$INI$SATQ$, $SATQ$CID$SATQ$, $SATQ$Central Ideas and Details$SATQ$, $SATQ$E$SATQ$, 3, $SATQ$mcq$SATQ$, $SATQ$<p>Archaeologist Veronica Waweru visited the Lewa Wildlife Conservancy in Kenya. While exploring there, Waweru noticed many rows of shallow pits carved into stone. Waweru believed the pits could have been used as game boards to play ancient versions of mancala, a two-person strategy game that is still popular today. Some of the more recent pits were carved on top of older pits. This led Waweru to think that the game was played at the site for a long time.</p>$SATQ$, $SATQ$<p>According to the text, why does Waweru think that mancala was played at the site for a long time?</p>$SATQ$, $SATQ$[{"id":"8f1a5e68-14c4-4e69-817c-fc90e83dd7ed","content":"<p>Some of the newer pits were carved on top of the older pits.&nbsp;</p>"},{"id":"22c10d35-2ddf-4c99-9f52-04c87e608032","content":"<p>She noticed many rows of shallow pits carved into stone.</p>"},{"id":"d8d9d390-8cfd-4839-9437-b79d5ab02696","content":"<p>She discovered the pits at the Lewa Wildlife Conservancy.</p>"},{"id":"652b94be-67fc-4d94-8500-0ad92c768b56","content":"<p>Some of the pits were shallow and others were quite deep.</p>"}]$SATQ$::jsonb, $SATQ$["A"]$SATQ$::jsonb, $SATQ$["8f1a5e68-14c4-4e69-817c-fc90e83dd7ed"]$SATQ$::jsonb, $SATQ$<p>Choice A is the best answer because it presents a statement about Veronica Waweru&rsquo;s thinking that is supported by the text. The text begins by discussing Waweru&rsquo;s discovery of evidence that ancient versions of the board game mancala had been played at a site in the Lewa Wildlife Conservancy. The evidence consisted of many rows of shallow pits carved into stone. The text goes on to state that some newer pits were carved on top of older pits, suggesting that people may have continued to play the game there over multiple generations, creating new pits over time. The text then explicitly states that the presence of newer pits carved on top of older pits was precisely what caused Waweru to think that mancala had been played at the site for a long time.</p><p>Choice B is incorrect. While the text does state that Waweru "noticed many rows of shallow pits carved into stone," this observation led her to believe that the pits could have been used as game boards for ancient versions of mancala but did not specifically suggest to her that the game had been played at the site for a long time. The multiple rows of pits merely suggest that these pits functioned as part of a game board; they don&rsquo;t necessarily indicate how long the site had been used for that purpose. Rather, it was the fact that there appeared to be newer pits carved on top of older pits that led Waweru to think that mancala had been played at the site for a long time. Choice C is incorrect. Although the text states that Waweru found the pits at the Lewa Wildlife Conservancy, this isn&rsquo;t the reason the text gives for why she thought that mancala had been played at the site for a long time. The location of the discovery only provides information about where the game was played, not how long the game had been played there. Choice D is incorrect because the text doesn&rsquo;t mention any variation in the depth of the pits. The text only describes the pits collectively as shallow and doesn&rsquo;t indicate that the depth of the pits factored into Waweru&rsquo;s thinking about how long the site had been used for playing mancala.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"2edd7ffe","external_id":"f4d5a3e3-3526-4403-9a50-294a663640d4","vaultid":null,"uId":"abe0e4e9-c2e7-4447-a06d-b5b5186f9a23","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"INI","domain":"Information and Ideas","skill_cd":"CID","skill_desc":"Central Ideas and Details","difficulty":"E","score_band_range_cd":3,"type":"mcq","stimulus":"<p>Archaeologist Veronica Waweru visited the Lewa Wildlife Conservancy in Kenya. While exploring there, Waweru noticed many rows of shallow pits carved into stone. Waweru believed the pits could have been used as game boards to play ancient versions of mancala, a two-person strategy game that is still popular today. Some of the more recent pits were carved on top of older pits. This led Waweru to think that the game was played at the site for a long time.</p>","stem":"<p>According to the text, why does Waweru think that mancala was played at the site for a long time?</p>","answerOptions":[{"id":"8f1a5e68-14c4-4e69-817c-fc90e83dd7ed","content":"<p>Some of the newer pits were carved on top of the older pits.&nbsp;</p>"},{"id":"22c10d35-2ddf-4c99-9f52-04c87e608032","content":"<p>She noticed many rows of shallow pits carved into stone.</p>"},{"id":"d8d9d390-8cfd-4839-9437-b79d5ab02696","content":"<p>She discovered the pits at the Lewa Wildlife Conservancy.</p>"},{"id":"652b94be-67fc-4d94-8500-0ad92c768b56","content":"<p>Some of the pits were shallow and others were quite deep.</p>"}],"keys":["8f1a5e68-14c4-4e69-817c-fc90e83dd7ed"],"correct_answer":["A"],"rationale":"<p>Choice A is the best answer because it presents a statement about Veronica Waweru&rsquo;s thinking that is supported by the text. The text begins by discussing Waweru&rsquo;s discovery of evidence that ancient versions of the board game mancala had been played at a site in the Lewa Wildlife Conservancy. The evidence consisted of many rows of shallow pits carved into stone. The text goes on to state that some newer pits were carved on top of older pits, suggesting that people may have continued to play the game there over multiple generations, creating new pits over time. The text then explicitly states that the presence of newer pits carved on top of older pits was precisely what caused Waweru to think that mancala had been played at the site for a long time.</p><p>Choice B is incorrect. While the text does state that Waweru \"noticed many rows of shallow pits carved into stone,\" this observation led her to believe that the pits could have been used as game boards for ancient versions of mancala but did not specifically suggest to her that the game had been played at the site for a long time. The multiple rows of pits merely suggest that these pits functioned as part of a game board; they don&rsquo;t necessarily indicate how long the site had been used for that purpose. Rather, it was the fact that there appeared to be newer pits carved on top of older pits that led Waweru to think that mancala had been played at the site for a long time. Choice C is incorrect. Although the text states that Waweru found the pits at the Lewa Wildlife Conservancy, this isn&rsquo;t the reason the text gives for why she thought that mancala had been played at the site for a long time. The location of the discovery only provides information about where the game was played, not how long the game had been played there. Choice D is incorrect because the text doesn&rsquo;t mention any variation in the depth of the pits. The text only describes the pits collectively as shallow and doesn&rsquo;t indicate that the depth of the pits factored into Waweru&rsquo;s thinking about how long the site had been used for playing mancala.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1755117061193,"updateDate":1755117061193}$SATQ$::jsonb, 1755117061193, 1755117061193),
    ($SATQ$2ef8e367$SATQ$, $SATQ$eee3d6e7-d7b3-4071-b69b-99c74c898d45$SATQ$::uuid, $SATQ$03efd007-df90-4849-b0f8-06d6647477ce$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Information and Ideas$SATQ$, $SATQ$INI$SATQ$, $SATQ$COE$SATQ$, $SATQ$Command of Evidence$SATQ$, $SATQ$M$SATQ$, 5, $SATQ$mcq$SATQ$, $SATQ$<p>&ldquo;To You&rdquo; is an 1856 poem by Walt Whitman. In the poem, Whitman suggests that he deeply understands the reader, whom he addresses directly, writing, <span aria-hidden="true">______</span><span class="sr-only">blank</span></p>$SATQ$, $SATQ$<p>Which quotation from &ldquo;To You&rdquo; most effectively illustrates the claim?</p>$SATQ$, $SATQ$[{"id":"f8fc5ca0-1bb1-4acd-a94e-a2e96f71d719","content":"<p>&ldquo;Your true soul and body appear before me.&rdquo;</p>"},{"id":"e1728e69-ab66-4480-a74d-c8dea5ae0669","content":"<p>&ldquo;Whoever you are, now I place my hand upon you, that you be my poem.&rdquo;</p>"},{"id":"1671c062-9714-49c4-875b-db02bb32405a","content":"<p>&ldquo;I should have made my way straight to you long ago.&rdquo;</p>"},{"id":"8df3ace6-8649-4315-8853-548da8c83df2","content":"<p>&ldquo;Whoever you are, I fear you are walking the walks of dreams.&rdquo;</p>"}]$SATQ$::jsonb, $SATQ$["A"]$SATQ$::jsonb, $SATQ$["f8fc5ca0-1bb1-4acd-a94e-a2e96f71d719"]$SATQ$::jsonb, $SATQ$<p>Choice A is the best answer because it most directly illustrates the text&rsquo;s claim about Whitman&rsquo;s poem, &ldquo;To You.&rdquo; The text says that in this poem, Whitman suggests that he deeply understands the poem&rsquo;s reader. This quotation says that the reader&rsquo;s &ldquo;true soul and body appear before&rdquo; Whitman, thereby asserting that he can see the reader as the reader truly is, suggesting that he deeply understands the reader. </p><p>Choice B is incorrect because this quotation describes Whitman making the reader the subject of the poem (&ldquo;you be my poem&rdquo;), not Whitman deeply understanding the reader.&nbsp;Choice C is incorrect because instead of suggesting that Whitman deeply understands the reader, it emphasizes Whitman&rsquo;s regret at not having addressed the reader sooner.&nbsp;Choice D is incorrect. Although this quotation shows Whitman directly addressing the reader and expressing concern about the reader, it doesn&rsquo;t illustrate the idea that Whitman suggests that he deeply understands the reader. The quotation is simply expressing concern about the reader, which doesn&rsquo;t necessarily imply deep understanding of the reader.&nbsp;</p>$SATQ$, false, 0, $SATQ$P89-T036$SATQ$, $SATQ$$SATQ$, $SATQ$bfa6259d-a12b-4b83-a58d-3e31c1ed8365$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"2ef8e367","external_id":"eee3d6e7-d7b3-4071-b69b-99c74c898d45","vaultid":"03efd007-df90-4849-b0f8-06d6647477ce","uId":"9bd1fa38-c29e-41aa-9a28-d947c2cb62b5","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"INI","domain":"Information and Ideas","skill_cd":"COE","skill_desc":"Command of Evidence","difficulty":"M","score_band_range_cd":5,"type":"mcq","stimulus":"<p>&ldquo;To You&rdquo; is an 1856 poem by Walt Whitman. In the poem, Whitman suggests that he deeply understands the reader, whom he addresses directly, writing, <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span></p>","stem":"<p>Which quotation from &ldquo;To You&rdquo; most effectively illustrates the claim?</p>","answerOptions":[{"id":"f8fc5ca0-1bb1-4acd-a94e-a2e96f71d719","content":"<p>&ldquo;Your true soul and body appear before me.&rdquo;</p>"},{"id":"e1728e69-ab66-4480-a74d-c8dea5ae0669","content":"<p>&ldquo;Whoever you are, now I place my hand upon you, that you be my poem.&rdquo;</p>"},{"id":"1671c062-9714-49c4-875b-db02bb32405a","content":"<p>&ldquo;I should have made my way straight to you long ago.&rdquo;</p>"},{"id":"8df3ace6-8649-4315-8853-548da8c83df2","content":"<p>&ldquo;Whoever you are, I fear you are walking the walks of dreams.&rdquo;</p>"}],"keys":["f8fc5ca0-1bb1-4acd-a94e-a2e96f71d719"],"correct_answer":["A"],"rationale":"<p>Choice A is the best answer because it most directly illustrates the text&rsquo;s claim about Whitman&rsquo;s poem, &ldquo;To You.&rdquo; The text says that in this poem, Whitman suggests that he deeply understands the poem&rsquo;s reader. This quotation says that the reader&rsquo;s &ldquo;true soul and body appear before&rdquo; Whitman, thereby asserting that he can see the reader as the reader truly is, suggesting that he deeply understands the reader. </p><p>Choice B is incorrect because this quotation describes Whitman making the reader the subject of the poem (&ldquo;you be my poem&rdquo;), not Whitman deeply understanding the reader.&nbsp;Choice C is incorrect because instead of suggesting that Whitman deeply understands the reader, it emphasizes Whitman&rsquo;s regret at not having addressed the reader sooner.&nbsp;Choice D is incorrect. Although this quotation shows Whitman directly addressing the reader and expressing concern about the reader, it doesn&rsquo;t illustrate the idea that Whitman suggests that he deeply understands the reader. The quotation is simply expressing concern about the reader, which doesn&rsquo;t necessarily imply deep understanding of the reader.&nbsp;</p>","parenttemplatename":"P89-T036","parenttemplateid":"","templateclusterid":"bfa6259d-a12b-4b83-a58d-3e31c1ed8365","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959378,"updateDate":1691007959378}$SATQ$::jsonb, 1691007959378, 1691007959378),
    ($SATQ$2fdfe002$SATQ$, $SATQ$2feba5ee-68da-40e5-9ac9-a2d6595ea46b$SATQ$::uuid, $SATQ$4760d20a-02bb-4946-9130-050ae362003f$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Information and Ideas$SATQ$, $SATQ$INI$SATQ$, $SATQ$CID$SATQ$, $SATQ$Central Ideas and Details$SATQ$, $SATQ$H$SATQ$, 6, $SATQ$mcq$SATQ$, $SATQ$<p>The following text is adapted from Countee Cullen&rsquo;s 1926 poem &ldquo;Thoughts in a Zoo.&rdquo;&nbsp;</p>
<blockquote class="dap_poemexcerpt">
<p>They in their cruel traps, and we in ours,&nbsp;&nbsp;</p>
<p>Survey each other&rsquo;s rage, and pass the hours&nbsp;&nbsp;</p>
<p>Commiserating each the other&rsquo;s woe,&nbsp;&nbsp;</p>
<p>To mitigate his own pain&rsquo;s fiery glow.&nbsp;&nbsp;</p>
<p>Man could but little proffer in exchange&nbsp;&nbsp;</p>
<p>Save that his cages have a larger range.&nbsp;&nbsp;</p>
<p>That lion with his lordly, untamed heart&nbsp;&nbsp;</p>
<p>Has in some man his human counterpart,</p>
<p>Some lofty soul in dreams and visions wrapped,&nbsp;&nbsp;</p>
<p>But in the stifling flesh securely trapped.</p>
</blockquote>$SATQ$, $SATQ$<p>Based on the text, what challenge do humans sometimes experience?</p>$SATQ$, $SATQ$[{"id":"54beed80-7eb8-41ed-abf5-8ebeb0fc3048","content":"<p>They cannot effectively tame certain wild animals because of a lack of compassion.</p>"},{"id":"eb6a2cd0-eff3-4d03-8d99-c7423c96b439","content":"<p>They cannot focus on setting attainable goals because of a lack of motivation.</p>"},{"id":"eaa4379a-1060-4ba9-b8a9-b56013f2042f","content":"<p>They quickly become frustrated when faced with difficult tasks because of a lack of self-control.</p>"},{"id":"85aef49b-35cd-471c-a3fd-dff8ed5a71f3","content":"<p>They have aspirations that cannot be fulfilled because of certain limitations.</p>"}]$SATQ$::jsonb, $SATQ$["D"]$SATQ$::jsonb, $SATQ$["85aef49b-35cd-471c-a3fd-dff8ed5a71f3"]$SATQ$::jsonb, $SATQ$<p>Choice D is the best answer. The text metaphorically likens humans to animals in a zoo, suggesting that humans have dreams that they cannot fulfill because they are trapped. </p><p>Choice A is incorrect. The speaker says that the lion has an &ldquo;untamed heart,&rdquo; but the speaker doesn&rsquo;t actually mention anything about humans taming wild animals or a lack of compassion. Choice B is incorrect. The speaker doesn&rsquo;t suggest that humans lack motivation. Rather, the speaker thinks that humans are &ldquo;trapped&rdquo; and prevented from achieving their dreams. Choice C is incorrect. The speaker doesn&rsquo;t mention anything about humans becoming frustrated or lacking self-control. Rather, the speaker thinks that humans are &ldquo;trapped&rdquo; and prevented from achieving their dreams. </p>$SATQ$, false, 0, $SATQ$OSP-KA-CID-H005$SATQ$, $SATQ$$SATQ$, $SATQ$8170e58d-ca33-4ef4-a5d0-2de024ba6fb7$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"2fdfe002","external_id":"2feba5ee-68da-40e5-9ac9-a2d6595ea46b","vaultid":"4760d20a-02bb-4946-9130-050ae362003f","uId":"18d89553-8cb9-4392-8bc5-752be2b6f755","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"INI","domain":"Information and Ideas","skill_cd":"CID","skill_desc":"Central Ideas and Details","difficulty":"H","score_band_range_cd":6,"type":"mcq","stimulus":"<p>The following text is adapted from Countee Cullen&rsquo;s 1926 poem &ldquo;Thoughts in a Zoo.&rdquo;&nbsp;</p>\n<blockquote class=\"dap_poemexcerpt\">\n<p>They in their cruel traps, and we in ours,&nbsp;&nbsp;</p>\n<p>Survey each other&rsquo;s rage, and pass the hours&nbsp;&nbsp;</p>\n<p>Commiserating each the other&rsquo;s woe,&nbsp;&nbsp;</p>\n<p>To mitigate his own pain&rsquo;s fiery glow.&nbsp;&nbsp;</p>\n<p>Man could but little proffer in exchange&nbsp;&nbsp;</p>\n<p>Save that his cages have a larger range.&nbsp;&nbsp;</p>\n<p>That lion with his lordly, untamed heart&nbsp;&nbsp;</p>\n<p>Has in some man his human counterpart,</p>\n<p>Some lofty soul in dreams and visions wrapped,&nbsp;&nbsp;</p>\n<p>But in the stifling flesh securely trapped.</p>\n</blockquote>","stem":"<p>Based on the text, what challenge do humans sometimes experience?</p>","answerOptions":[{"id":"54beed80-7eb8-41ed-abf5-8ebeb0fc3048","content":"<p>They cannot effectively tame certain wild animals because of a lack of compassion.</p>"},{"id":"eb6a2cd0-eff3-4d03-8d99-c7423c96b439","content":"<p>They cannot focus on setting attainable goals because of a lack of motivation.</p>"},{"id":"eaa4379a-1060-4ba9-b8a9-b56013f2042f","content":"<p>They quickly become frustrated when faced with difficult tasks because of a lack of self-control.</p>"},{"id":"85aef49b-35cd-471c-a3fd-dff8ed5a71f3","content":"<p>They have aspirations that cannot be fulfilled because of certain limitations.</p>"}],"keys":["85aef49b-35cd-471c-a3fd-dff8ed5a71f3"],"correct_answer":["D"],"rationale":"<p>Choice D is the best answer. The text metaphorically likens humans to animals in a zoo, suggesting that humans have dreams that they cannot fulfill because they are trapped. </p><p>Choice A is incorrect. The speaker says that the lion has an &ldquo;untamed heart,&rdquo; but the speaker doesn&rsquo;t actually mention anything about humans taming wild animals or a lack of compassion. Choice B is incorrect. The speaker doesn&rsquo;t suggest that humans lack motivation. Rather, the speaker thinks that humans are &ldquo;trapped&rdquo; and prevented from achieving their dreams. Choice C is incorrect. The speaker doesn&rsquo;t mention anything about humans becoming frustrated or lacking self-control. Rather, the speaker thinks that humans are &ldquo;trapped&rdquo; and prevented from achieving their dreams. </p>","parenttemplatename":"OSP-KA-CID-H005","parenttemplateid":"","templateclusterid":"8170e58d-ca33-4ef4-a5d0-2de024ba6fb7","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959360,"updateDate":1691007959360}$SATQ$::jsonb, 1691007959360, 1691007959360),
    ($SATQ$303537cf$SATQ$, $SATQ$6beb6b1f-fb0d-4ffd-bf54-7e868f01ee48$SATQ$::uuid, $SATQ$23520643-2ffc-46e4-94dc-2e525a48bbbb$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Information and Ideas$SATQ$, $SATQ$INI$SATQ$, $SATQ$CID$SATQ$, $SATQ$Central Ideas and Details$SATQ$, $SATQ$H$SATQ$, 7, $SATQ$mcq$SATQ$, $SATQ$<p>The following text is adapted from Lewis Carroll&rsquo;s 1889 satirical novel <em>Sylvie and Bruno</em>. A crowd has gathered outside a room belonging to the Warden, an official who reports to the Lord Chancellor.</p>
<div style="padding-left:1em"><p>One man, who was more excited than the rest, flung his hat high into the air, and shouted (as well as I could make out) &ldquo;Who roar for the Sub-Warden?&rdquo; Everybody roared, but whether it was for the Sub-Warden, or not, did not clearly appear: some were shouting &ldquo;Bread!&rdquo; and some &ldquo;Taxes!&rdquo;, but no one seemed to know what it was they really wanted.</p>
<p>All this I saw from the open window of the Warden&rsquo;s breakfast-saloon, looking across the shoulder of the Lord Chancellor.</p>
<p>&ldquo;What can it all mean?&rdquo; he kept repeating to himself. &ldquo;I never heard such shouting before&mdash;and at this time of the morning, too! And with such unanimity!&rdquo;</p></div>$SATQ$, $SATQ$<p>Based on the text, how does the Lord Chancellor respond to the crowd?</p>$SATQ$, $SATQ$[{"id":"6a4ab01c-b912-40a3-9055-56253d2ae5a8","content":"<p>He asks about the meaning of the crowd&rsquo;s shouting, even though he claims to know what the crowd wants.</p>"},{"id":"6cea1364-e917-4fbd-a386-491d392ca9ad","content":"<p>He indicates a desire to speak to the crowd, even though the crowd has asked to speak to the Sub-Warden.</p>"},{"id":"f05ec1df-b2d6-4ed7-b95f-5db7a9184dd8","content":"<p>He expresses sympathy for the crowd&rsquo;s demands, even though the crowd&rsquo;s shouting annoys him.</p>"},{"id":"c03b22b1-c7f4-41cc-9a3e-c1b51f5a7fd2","content":"<p>He describes the crowd as being united, even though the crowd clearly appears otherwise.</p>"}]$SATQ$::jsonb, $SATQ$["D"]$SATQ$::jsonb, $SATQ$["c03b22b1-c7f4-41cc-9a3e-c1b51f5a7fd2"]$SATQ$::jsonb, $SATQ$<p>Choice D is the best answer because it presents a statement about how the Lord Chancellor responds to the crowd that is supported by the text. The text indicates that the people in the crowd are roaring and shouting &ldquo;Bread!&rdquo; or &ldquo;Taxes!&rdquo; and presents them as not knowing what they really want. The Lord Chancellor&rsquo;s response is to ask what their shouting means but also to observe that they&rsquo;re shouting with &ldquo;unanimity,&rdquo; or total agreement. Clearly, this isn&rsquo;t the case, which supports the statement that the Lord Chancellor describes the crowd as being united even though it&rsquo;s not.&nbsp;</p><p>Choice A is incorrect because it isn&rsquo;t supported by the text. Although the text indicates that the Lord Chancellor asks about the meaning of the crowd&rsquo;s shouting, it doesn&rsquo;t suggest that he knows what the crowd really wants. Choice B is incorrect because the text doesn&rsquo;t suggest that the Lord Chancellor wants to speak to the crowd. Furthermore, the text doesn&rsquo;t indicate that the crowd wants to hear from the Sub-Warden. Although the crowd roars when asked &ldquo;Who roar for the Sub-Warden?&rdquo; it&rsquo;s unclear what the roaring means. Choice C is incorrect because the text doesn&rsquo;t suggest that the Lord Chancellor knows of or sympathizes with the crowd&rsquo;s demands. In addition, the text doesn&rsquo;t indicate that the crowd&rsquo;s shouting annoys the Lord Chancellor, just that it causes him to keep repeating &ldquo;What can it all mean?&rdquo; &nbsp;</p>$SATQ$, false, 0, $SATQ$OSP-010-CID$SATQ$, $SATQ$$SATQ$, $SATQ$28b2484e-dfcc-462c-b2de-c741d3392f00$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"303537cf","external_id":"6beb6b1f-fb0d-4ffd-bf54-7e868f01ee48","vaultid":"23520643-2ffc-46e4-94dc-2e525a48bbbb","uId":"e5709401-b986-4b9c-beb9-0a0f59cb5410","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"INI","domain":"Information and Ideas","skill_cd":"CID","skill_desc":"Central Ideas and Details","difficulty":"H","score_band_range_cd":7,"type":"mcq","stimulus":"<p>The following text is adapted from Lewis Carroll&rsquo;s 1889 satirical novel <em>Sylvie and Bruno</em>. A crowd has gathered outside a room belonging to the Warden, an official who reports to the Lord Chancellor.</p>\n<div style=\"padding-left:1em\"><p>One man, who was more excited than the rest, flung his hat high into the air, and shouted (as well as I could make out) &ldquo;Who roar for the Sub-Warden?&rdquo; Everybody roared, but whether it was for the Sub-Warden, or not, did not clearly appear: some were shouting &ldquo;Bread!&rdquo; and some &ldquo;Taxes!&rdquo;, but no one seemed to know what it was they really wanted.</p>\n<p>All this I saw from the open window of the Warden&rsquo;s breakfast-saloon, looking across the shoulder of the Lord Chancellor.</p>\n<p>&ldquo;What can it all mean?&rdquo; he kept repeating to himself. &ldquo;I never heard such shouting before&mdash;and at this time of the morning, too! And with such unanimity!&rdquo;</p></div>","stem":"<p>Based on the text, how does the Lord Chancellor respond to the crowd?</p>","answerOptions":[{"id":"6a4ab01c-b912-40a3-9055-56253d2ae5a8","content":"<p>He asks about the meaning of the crowd&rsquo;s shouting, even though he claims to know what the crowd wants.</p>"},{"id":"6cea1364-e917-4fbd-a386-491d392ca9ad","content":"<p>He indicates a desire to speak to the crowd, even though the crowd has asked to speak to the Sub-Warden.</p>"},{"id":"f05ec1df-b2d6-4ed7-b95f-5db7a9184dd8","content":"<p>He expresses sympathy for the crowd&rsquo;s demands, even though the crowd&rsquo;s shouting annoys him.</p>"},{"id":"c03b22b1-c7f4-41cc-9a3e-c1b51f5a7fd2","content":"<p>He describes the crowd as being united, even though the crowd clearly appears otherwise.</p>"}],"keys":["c03b22b1-c7f4-41cc-9a3e-c1b51f5a7fd2"],"correct_answer":["D"],"rationale":"<p>Choice D is the best answer because it presents a statement about how the Lord Chancellor responds to the crowd that is supported by the text. The text indicates that the people in the crowd are roaring and shouting &ldquo;Bread!&rdquo; or &ldquo;Taxes!&rdquo; and presents them as not knowing what they really want. The Lord Chancellor&rsquo;s response is to ask what their shouting means but also to observe that they&rsquo;re shouting with &ldquo;unanimity,&rdquo; or total agreement. Clearly, this isn&rsquo;t the case, which supports the statement that the Lord Chancellor describes the crowd as being united even though it&rsquo;s not.&nbsp;</p><p>Choice A is incorrect because it isn&rsquo;t supported by the text. Although the text indicates that the Lord Chancellor asks about the meaning of the crowd&rsquo;s shouting, it doesn&rsquo;t suggest that he knows what the crowd really wants. Choice B is incorrect because the text doesn&rsquo;t suggest that the Lord Chancellor wants to speak to the crowd. Furthermore, the text doesn&rsquo;t indicate that the crowd wants to hear from the Sub-Warden. Although the crowd roars when asked &ldquo;Who roar for the Sub-Warden?&rdquo; it&rsquo;s unclear what the roaring means. Choice C is incorrect because the text doesn&rsquo;t suggest that the Lord Chancellor knows of or sympathizes with the crowd&rsquo;s demands. In addition, the text doesn&rsquo;t indicate that the crowd&rsquo;s shouting annoys the Lord Chancellor, just that it causes him to keep repeating &ldquo;What can it all mean?&rdquo; &nbsp;</p>","parenttemplatename":"OSP-010-CID","parenttemplateid":"","templateclusterid":"28b2484e-dfcc-462c-b2de-c741d3392f00","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959314,"updateDate":1691007959314}$SATQ$::jsonb, 1691007959314, 1691007959314),
    ($SATQ$303bcc41$SATQ$, $SATQ$e03cf173-646e-41f7-b95d-eed2441f61e7$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Information and Ideas$SATQ$, $SATQ$INI$SATQ$, $SATQ$COE$SATQ$, $SATQ$Command of Evidence$SATQ$, $SATQ$E$SATQ$, 1, $SATQ$mcq$SATQ$, $SATQ$<figure class="image"><svg xmlns="http://www.w3.org/2000/svg" width="380" height="515.10302734375" viewBox="0 0 380 515.10302734375" role="img" aria-label="Bar graph titled Top Four Species of Wild Land Mammals by Global Biomass. The horizontal axis is labeled Species. 4 bars are shown. The vertical axis is labeled Global biomass, in millions of metric tons. It ranges from 0 to 3.0 in increments of 0.5. Refer to long description."><g id="ed420550-79eb-48d4-af01-cd27cdd08afd" data-name="Layer 1"><defs>
