    </defs><line xmlns="http://www.w3.org/2000/svg" x1="93" y1="96" x2="365" y2="96" fill="none" stroke="#000000" stroke-linecap="round" stroke-linejoin="round" stroke-width="0.9"/><line xmlns="http://www.w3.org/2000/svg" x1="87" y1="96" x2="99" y2="96" fill="none" stroke="#000000" stroke-linecap="round" stroke-linejoin="round" stroke-width="0.9"/><text text-anchor="end" transform="translate(81 102)" fill="#000000" font-size="19.84" font-family="Crimson Text">3.0</text><line xmlns="http://www.w3.org/2000/svg" x1="93" y1="129.33333333333334" x2="365" y2="129.33333333333334" fill="none" stroke="#000000" stroke-linecap="round" stroke-linejoin="round" stroke-width="0.9"/><line xmlns="http://www.w3.org/2000/svg" x1="87" y1="129.33333333333334" x2="99" y2="129.33333333333334" fill="none" stroke="#000000" stroke-linecap="round" stroke-linejoin="round" stroke-width="0.9"/><text text-anchor="end" transform="translate(81 135.33333333333334)" fill="#000000" font-size="19.84" font-family="Crimson Text">2.5</text><line xmlns="http://www.w3.org/2000/svg" x1="93" y1="162.66666666666669" x2="365" y2="162.66666666666669" fill="none" stroke="#000000" stroke-linecap="round" stroke-linejoin="round" stroke-width="0.9"/><line xmlns="http://www.w3.org/2000/svg" x1="87" y1="162.66666666666669" x2="99" y2="162.66666666666669" fill="none" stroke="#000000" stroke-linecap="round" stroke-linejoin="round" stroke-width="0.9"/><text text-anchor="end" transform="translate(81 168.66666666666669)" fill="#000000" font-size="19.84" font-family="Crimson Text">2.0</text><line xmlns="http://www.w3.org/2000/svg" x1="93" y1="196" x2="365" y2="196" fill="none" stroke="#000000" stroke-linecap="round" stroke-linejoin="round" stroke-width="0.9"/><line xmlns="http://www.w3.org/2000/svg" x1="87" y1="196" x2="99" y2="196" fill="none" stroke="#000000" stroke-linecap="round" stroke-linejoin="round" stroke-width="0.9"/><text text-anchor="end" transform="translate(81 202)" fill="#000000" font-size="19.84" font-family=