101.765625 282)\" fill=\"#000000\" font-size=\"19.84\" font-family=\"Crimson Text\">10</text><line xmlns=\"http://www.w3.org/2000/svg\" x1=\"113.765625\" y1=\"296\" x2=\"435\" y2=\"296\" fill=\"none\" stroke=\"#000000\" stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"0.9\"/><line xmlns=\"http://www.w3.org/2000/svg\" x1=\"107.765625\" y1=\"296\" x2=\"119.765625\" y2=\"296\" fill=\"none\" stroke=\"#000000\" stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"0.9\"/><text text-anchor=\"end\" transform=\"translate(101.765625 302)\" fill=\"#000000\" font-size=\"19.84\" font-family=\"Crimson Text\">0</text><text text-anchor=\"middle\" transform=\"translate(24 196) rotate(-90)\" fill=\"#000000\" font-size=\"19.84\" font-family=\"Crimson Text\">Manganese to calcium ratio</text><text text-anchor=\"middle\" transform=\"translate(48 196) rotate(-90)\" fill=\"#000000\" font-size=\"19.84\" font-family=\"Crimson Text\">(micromoles per mole)</text><line xmlns=\"http://www.w3.org/2000/svg\" x1=\"113.765625\" y1=\"96\" x2=\"113.765625\" y2=\"296\" fill=\"none\" stroke=\"#000000\" stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"0.9\"/><line xmlns=\"http://www.w3.org/2000/svg\" x1=\"129.82734375\" x2=\"129.82734375\" y1=\"96\" y2=\"296\" fill=\"none\" stroke=\"#000000\" stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"0.9\"/><text xmlns=\"http://www.w3.org/2000/svg\" x=\"0\" y=\"0\" text-anchor=\"middle\" transform=\"translate(129.82734375 315.84)\" fill=\"#000000\" font-size=\"19.84\" font-family=\"Crimson Text\">2</text><line xmlns=\"http://www.w3.org/2000/svg\" x1=\"161.95078125\" x2=\"161.95078125\" y1=\"96\" y2=\"296\" fill=\"none\" stroke=\"#000000\" stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"0.9\"/><text xmlns=\"http://www.w3.org/2000/svg\" x=\"0\" y=\"0\" text-anchor=\"middle\" transform=\"translate(161.95078125 315.84)\" fill=\"#000000\" font-size=\"19.84\" font-family=\"Crimson Text\">4</text><line xmlns=\"http://www.w3.org/2000/svg\" x1=\"194.07421875\" x2=\"194.07421875\" y1=\"96\" y2=\"296\" fill=\"none\" stroke=\"#000000\" stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"0.9\"/><text xmlns=\"http://www.w3.org/2000/svg\" x=\"0\" y=\"0\" text-anchor=\"middle\" transform=\"translate(194.07421875 315.84)\" fill=\"#000000\" font-size=\"19.84\" font-family=\"Crimson Text\">6</text><line xmlns=\"http://www.w3.org/2000/svg\" x1=\"226.19765625\" x2=\"226.19765625\" y1=\"96\" y2=\"296\" fill=\"none\" stroke=\"#000000\" stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"0.9\"/><text xmlns=\"http://www.w3.org/2000/svg\" x=\"0\" y=\"0\" text-anchor=\"middle\" transform=\"translate(226.19765625 315.84)\" fill=\"#000000\" font-size=\"19.84\" font-family=\"Crimson Text\">8</text><line xmlns=\"http://www.w3.org/2000/svg\" x1=\"258.32109375\" x2=\"258.32109375\" y1=\"96\" y2=\"296\" fill=\"none\" stroke=\"#000000\" stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"0.9\"/><text xmlns=\"http://www.w3.org/2000/svg\" x=\"0\" y=\"0\" text-anchor=\"middle\" transform=\"translate(258.32109375 315.84)\" fill=\"#000000\" font-size=\"19.84\" font-family=\"Crimson Text\">10</text><line xmlns=\"http://www.w3.org/2000/svg\" x1=\"290.44453125\" x2=\"290.44453125\" y1=\"96\" y2=\"296\" fill=\"none\" stroke=\"#000000\" stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"0.9\"/><text xmlns=\"http://www.w3.org/2000/svg\" x=\"0\" y=\"0\" text-anchor=\"middle\" transform=\"translate(290.44453125 315.84)\" fill=\"#000000\" font-size=\"19.84\" font-family=\"Crimson Text\">12</text><line xmlns=\"http://www.w3.org/2000/svg\" x1=\"322.56796875000003\" x2=\"322.56796875000003\" y1=\"96\" y2=\"296\" fill=\"none\" stroke=\"#000000\" stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"0.9\"/><text xmlns=\"http://www.w3.org/2000/svg\" x=\"0\" y=\"0\" text-anchor=\"middle\" transform=\"translate(322.56796875000003 31